using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class ExcludeFromCodeCoverageRequirementTests
{
    private const string Source = """
        using MessagePack;

        namespace TestNs
        {
            [MessagePackObject]
            public class MyObject
            {
                [Key(0)]
                public int A { get; set; }

                [Key(1)]
                public MyEnum E { get; set; }
            }

            [MessagePackObject(true)]
            public class MyMapObject
            {
                public int B { get; set; }
            }

            public enum MyEnum
            {
                X,
                Y,
            }

            [GeneratedMessagePackResolver]
            partial class MyResolver
            {
            }
        }
        """;

    private static async Task<List<INamedTypeSymbol>> GetGeneratedClassesAsync(params string[] preprocessorSymbols)
    {
        var parseOptions = new CSharpParseOptions(LanguageVersion.Latest, preprocessorSymbols: preprocessorSymbols);
        var frameworkRefs = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        IEnumerable<MetadataReference> references = frameworkRefs.Concat(ReferencesHelper.GetReferences(ReferencesSet.MessagePack));
        CSharpCompilation compilation = CSharpCompilation.Create(
            "ReceiptsTestAssembly",
            new[] { CSharpSyntaxTree.ParseText(Source, parseOptions) },
            references,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        GeneratorDriver driver = CSharpGeneratorDriver.Create(
            new[] { new global::MessagePack.SourceGenerator.MessagePackGenerator().AsSourceGenerator() },
            parseOptions: parseOptions);
        driver = driver.RunGeneratorsAndUpdateCompilation(compilation, out Compilation output, out ImmutableArray<Diagnostic> generatorDiagnostics);
        Assert.Empty(generatorDiagnostics.Where(d => d.Severity == DiagnosticSeverity.Error));

        var originalTrees = compilation.SyntaxTrees.ToHashSet();
        var result = new List<INamedTypeSymbol>();
        foreach (SyntaxTree tree in output.SyntaxTrees.Where(t => !originalTrees.Contains(t)))
        {
            SemanticModel model = output.GetSemanticModel(tree);
            foreach (ClassDeclarationSyntax cds in tree.GetRoot().DescendantNodes().OfType<ClassDeclarationSyntax>())
            {
                if (model.GetDeclaredSymbol(cds) is INamedTypeSymbol symbol && (symbol.Name.EndsWith("Formatter", StringComparison.Ordinal) || symbol.Name == "MyResolver"))
                {
                    result.Add(symbol);
                }
            }
        }

        return result;
    }

    private static bool HasExcludeFromCodeCoverage(INamedTypeSymbol symbol)
        => symbol.GetAttributes().Any(a => a.AttributeClass?.Name == "ExcludeFromCodeCoverageAttribute");

    [Fact]
    public async Task GeneratedFormattersAreExcludedFromCodeCoverage()
    {
        List<INamedTypeSymbol> classes = await GetGeneratedClassesAsync();
        var formatters = classes.Where(c => c.Name.EndsWith("Formatter", StringComparison.Ordinal)).ToList();
        Assert.NotEmpty(formatters);
        foreach (INamedTypeSymbol formatter in formatters)
        {
            Assert.True(HasExcludeFromCodeCoverage(formatter), $"Generated formatter {formatter.ToDisplayString()} lacks ExcludeFromCodeCoverage.");
        }
    }

    [Fact]
    public async Task GeneratedResolverIsExcludedFromCodeCoverage()
    {
        List<INamedTypeSymbol> classes = await GetGeneratedClassesAsync();
        INamedTypeSymbol? resolver = classes.FirstOrDefault(c => c.Name == "MyResolver");
        Assert.NotNull(resolver);
        Assert.True(HasExcludeFromCodeCoverage(resolver!), "Generated resolver lacks ExcludeFromCodeCoverage.");
    }
}

