    [Fact]
    public async Task GeneratedTypesAreDecoratedWhenTargetingNetStandard20()
    {
        List<INamedTypeSymbol> classes = await GetGeneratedClassesAsync("NETSTANDARD2_0", "NETSTANDARD");
        Assert.NotEmpty(classes);
        foreach (INamedTypeSymbol type in classes)
