        List<INamedTypeSymbol> classes = await GetGeneratedClassesAsync("NETFRAMEWORK", "NET472");
        Assert.NotEmpty(classes);
        foreach (INamedTypeSymbol type in classes)
        {
            Assert.True(HasExcludeFromCodeCoverage(type), $"Generated type {type.ToDisplayString()} lacks ExcludeFromCodeCoverage when NETFRAMEWORK is defined.");
        }
    }
}
